with metrics as (select *, avg(sqft) over (partition by city order by opened_date, id rows between 3 preceding and current row) as last4_avg_sqft, max(sqft) over (partition by city order by opened_date, id rows between 3 preceding and current row) as last4_max_sqft, sum(sqft) over (partition by city order by opened_date, id rows between 3 preceding and current row) as last4_sum_sqft, min(sqft) over (partition by city order by opened_date, id rows between 3 preceding and current row) as last4_min_sqft from stores where sqft = 13169) select id, store_name, sqft, last4_max_sqft, last4_sum_sqft, last4_min_sqft from metrics;
